package io.github.ningpp.compat;

/** Replacement for System.DirectoryServices.ActiveDirectory.ActiveDirectoryObjectNotFoundException (generated by CSharpToJava converter). */
public class ActiveDirectoryObjectNotFoundException extends RuntimeException {
    private int hresult;
    public ActiveDirectoryObjectNotFoundException() { super(); }
    public ActiveDirectoryObjectNotFoundException(String message) { super(message); }
    public ActiveDirectoryObjectNotFoundException(String message, Throwable cause) { super(message, cause); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
